#!/bin/bash
set -e
APP=/root/opslabs
ts=$(date +%Y%m%d-%H%M%S)
mkdir -p "$APP/app/routes" "$APP/app/templates/admin"
cp "$APP/app/models.py" "$APP/app/models.py.bak.$ts" 2>/dev/null || true
cp "$APP/app/rbac.py" "$APP/app/rbac.py.bak.$ts" 2>/dev/null || true
cp "$APP/app/routes/admin.py" "$APP/app/routes/admin.py.bak.$ts" 2>/dev/null || true
cp "$APP/app/templates/admin/role_perms.html" "$APP/app/templates/admin/role_perms.html.bak.$ts" 2>/dev/null || true
cp "$APP/app/templates/admin/user_form.html" "$APP/app/templates/admin/user_form.html.bak.$ts" 2>/dev/null || true
cp "$APP/app/templates/admin/_layout.html" "$APP/app/templates/admin/_layout.html.bak.$ts" 2>/dev/null || true

base64 -d << 'MODELS_B64' > "$APP/app/models.py"

MODELS_B64

base64 -d << 'RBAC_B64' > "$APP/app/rbac.py"

RBAC_B64

base64 -d << 'ADMINPY_B64' > "$APP/app/routes/admin.py"

ADMINPY_B64

base64 -d << 'ROLEPERMSHTML_B64' > "$APP/app/templates/admin/role_perms.html"

ROLEPERMSHTML_B64

base64 -d << 'USERFORMHTML_B64' > "$APP/app/templates/admin/user_form.html"

USERFORMHTML_B64

base64 -d << 'LAYOUTHTML_B64' > "$APP/app/templates/admin/_layout.html"

LAYOUTHTML_B64

python3 -m py_compile "$APP/app/models.py" "$APP/app/rbac.py" "$APP/app/routes/admin.py"
systemctl restart opslabs-app.service
sleep 2
systemctl status opslabs-app.service --no-pager -l | head -15
journalctl -u opslabs-app.service -n 20 --no-pager
